package org.apache.commons.cli;

import static org.junit.jupiter.api.Assertions.*;

import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;

import org.junit.jupiter.api.Test;

class CommandLine_GetParsedOptionValuesTest {

    @Test
    void testPublicMethodReturnsDefaultWhenNoValues() throws Exception {
        // Arrange
        CommandLine cmd = new CommandLine(); // protected ctor accessible from same package
        Option opt = new Option("a", null, true, "description"); // hasArg = true
        String[] defaultValue = new String[] { "def1", "def2" };

        // Act
        String[] result = cmd.getParsedOptionValues(opt, defaultValue);

        // Assert
        assertNotNull(result, "result should not be null");
        assertArrayEquals(defaultValue, result, "Should return the provided default array when no option values present");
    }

    @Test
    void testPublicMethodReturnsOptionValuesWhenPresent() throws Exception {
        // Arrange
        CommandLine cmd = new CommandLine();
        Option opt = new Option("b", null, true, "description");
        // populate option values (getValuesList should be available)
        opt.getValuesList().add("v1");
        opt.getValuesList().add("v2");
        String[] defaultValue = new String[] { "def" };

        // Act
        String[] result = cmd.getParsedOptionValues(opt, defaultValue);

        // Assert
        assertNotNull(result);
        assertArrayEquals(new String[] { "v1", "v2" }, result, "Should return the option's values (as Strings) when present");
    }

    @Test
    void testPrivateOverloadUsesSupplierWhenNoValues() throws Exception {
        // Arrange
        CommandLine cmd = new CommandLine();
        Option opt = new Option("c", null, true, "description");

        // find private overloaded method getParsedOptionValues(Option, Supplier)
        Method privateMethod = findGetParsedOptionValuesWithSupplier();
        privateMethod.setAccessible(true);

        String[] supplied = new String[] { "supplied1" };
        @SuppressWarnings("unchecked")
        String[] result = (String[]) privateMethod.invoke(cmd, opt, (Supplier<String[]>) () -> supplied);

        // Assert
        assertNotNull(result);
        assertArrayEquals(supplied, result, "When option has no values, the supplier's array should be returned");
    }

    @Test
    void testPrivateOverloadDoesNotCallSupplierWhenValuesPresent() throws Exception {
        // Arrange
        CommandLine cmd = new CommandLine();
        Option opt = new Option("d", null, true, "description");
        opt.getValuesList().add("x");
        opt.getValuesList().add("y");

        // find private overloaded method getParsedOptionValues(Option, Supplier)
        Method privateMethod = findGetParsedOptionValuesWithSupplier();
        privateMethod.setAccessible(true);

        // supplier that would fail if invoked
        AtomicBoolean supplierCalled = new AtomicBoolean(false);
        @SuppressWarnings("unchecked")
        Supplier<String[]> failingSupplier = () -> {
            supplierCalled.set(true);
            throw new AssertionError("Supplier should not be called when option has values");
        };

        @SuppressWarnings("unchecked")
        String[] result = (String[]) privateMethod.invoke(cmd, opt, failingSupplier);

        // Assert
        assertFalse(supplierCalled.get(), "Supplier must not have been invoked");
        assertArrayEquals(new String[] { "x", "y" }, result, "Should return the option's values when present");
    }

    // Helper to reflectively locate the private getParsedOptionValues method that accepts a Supplier.
    private static Method findGetParsedOptionValuesWithSupplier() throws NoSuchMethodException {
        for (Method m : CommandLine.class.getDeclaredMethods()) {
            if (!m.getName().equals("getParsedOptionValues")) {
                continue;
            }
            Class<?>[] params = m.getParameterTypes();
            if (params.length == 2 && params[0] == Option.class && java.util.function.Supplier.class.isAssignableFrom(params[1])) {
                return m;
            }
        }
        // Fallback: try the exact signature (Option, Supplier)
        return CommandLine.class.getDeclaredMethod("getParsedOptionValues", Option.class, java.util.function.Supplier.class);
